INSERT INTO `v1_966c2f7454c4e894ecba04b787c6e240fa8636170c120ebe448376e8112c8cc2` VALUES ("魔法攻撃のダメージが小アップし、物理攻撃を行うキャラが行動する度にそのキャラの最大ＨＰに応じて最大99999の割合ダメージを与える。", 137, 2017, "界雷");
INSERT INTO `v1_966c2f7454c4e894ecba04b787c6e240fa8636170c120ebe448376e8112c8cc2` VALUES ("一定時間が経過するごとに、敵、味方全体のＴＰを中回復させる。", 146, 2017, "百花繚乱");
INSERT INTO `v1_966c2f7454c4e894ecba04b787c6e240fa8636170c120ebe448376e8112c8cc2` VALUES ("一定時間が経過するごとに、敵、味方全体に最大ＨＰに応じた最大20万の割合ダメージを与える。さらに、付与される継続ダメージが上昇する。", 147, 2017, "炎天烈日");
INSERT INTO `v1_966c2f7454c4e894ecba04b787c6e240fa8636170c120ebe448376e8112c8cc2` VALUES ("一定時間が経過するごとに、敵、味方全体の物理攻撃力、魔法攻撃力、物理防御力、魔法防御力をアップさせる。この効果の効果量は敵、味方を合わせた数に応じて増加する。", 148, 2017, "秋高馬肥");
INSERT INTO `v1_966c2f7454c4e894ecba04b787c6e240fa8636170c120ebe448376e8112c8cc2` VALUES ("敵、味方全体の行動速度を小ダウンさせる。このスキルの効果は他の行動速度変化スキルと重複する。さらに一定時間が経過するごとに、初期値より行動速度が低い状態のキャラに凍結状態を付与する。", 149, 2017, "寒気凛冽");
INSERT INTO `v1_966c2f7454c4e894ecba04b787c6e240fa8636170c120ebe448376e8112c8cc2` VALUES ("魔法攻撃のダメージが小ダウンする。", 162, 2017, "妨魔塵");
INSERT INTO `v1_966c2f7454c4e894ecba04b787c6e240fa8636170c120ebe448376e8112c8cc2` VALUES ("一定時間が経過するごとに、敵全体に最大ＨＰに応じた魔法割合ダメージを与える。さらに、キャラのＨＰが50％未満の場合、麻痺状態を付与する。この効果によるダメージでは、ＴＰが回復しない。この効果の状態異常はダメージを無効化しても付与される。", 164, 2017, "雷雲");
INSERT INTO `v1_966c2f7454c4e894ecba04b787c6e240fa8636170c120ebe448376e8112c8cc2` VALUES ("一定時間が経過するごとに、敵全体をノックバックさせる。", 169, 2017, "暴風");
INSERT INTO `v1_966c2f7454c4e894ecba04b787c6e240fa8636170c120ebe448376e8112c8cc2` VALUES ("一定時間が経過するごとに、敵全体の行動速度をバトル終了まで小ダウンさせる。さらに、物理攻撃力と魔法攻撃力をバトル終了まで小ダウンさせる。", 170, 2017, "豪雨");
INSERT INTO `v1_966c2f7454c4e894ecba04b787c6e240fa8636170c120ebe448376e8112c8cc2` VALUES ("物理攻撃クリティカル時のダメージが小アップする。", 175, 2017, "絶氷");
INSERT INTO `v1_966c2f7454c4e894ecba04b787c6e240fa8636170c120ebe448376e8112c8cc2` VALUES ("一定時間が経過するごとに、敵全体に最大ＨＰに応じた魔法割合ダメージを与える。この効果によるダメージでは、ＴＰが回復しない。", 186, 2017, "雷雲");
INSERT INTO `v1_966c2f7454c4e894ecba04b787c6e240fa8636170c120ebe448376e8112c8cc2` VALUES ("継続ダメージを与える状態異常のダメージの発生間隔と効果時間が延長される。", 207, 2017, "忌火");
INSERT INTO `v1_966c2f7454c4e894ecba04b787c6e240fa8636170c120ebe448376e8112c8cc2` VALUES ("一定時間が経過するごとに、敵、味方全体の物理攻撃力、魔法攻撃力をアップさせる。この効果の効果量は現在の対象の物理攻撃力、魔法攻撃力に応じて増加する。", 228, 2017, "マナの流脈");
INSERT INTO `v1_966c2f7454c4e894ecba04b787c6e240fa8636170c120ebe448376e8112c8cc2` VALUES ("一定時間が経過するごとに、敵、味方全体のＴＰを小回復させる。", 278, 2017, "眩境");
